236	    }
237	    out.push('\n');
238	
239	    if strict {
240	        out.push_str(
241	            "**Strict mode — fix before analysis.** Work Socratically with the operator: \
242	             propose concrete `residual add` / edits that clear these findings, wait for approval, \
243	             re-run `residual verify all`, then continue the skill. Do not invent architecture on a broken baseline.\n\n",
244	        );
245	    } else {
246	        out.push_str(
247	            "**Advisory mode — note and proceed.** Surface these findings to the operator, then jump into the skill. \
248	             Repair when ready; capture is not blocked. Still Socratic: gather freely, modify only with approval.\n\n",
249	        );
